-- Jeu de LecteurRetourAudience et EcrivainRetourAudience (« Retour d'audience », PROC_RETAUD), lot 7 du plan « RIG v3 100 %
-- fonctionnel » (plan-676a4b19). Identifiants 1 700 xxx (lot 7), roles 2026x17xxx. Les instances n'ont PAS de code affaire :
-- elles restent hors des listes d'instances des autres lots (MJUD, JOIN, XLIEN... joignent CODE_AFFAIRE).
-- Les tables V2 lues, aux types de RIG_DEV (Source\BaseDeDonnees\RigDatabase\dbo\Tables\*.sql de RigApplication), seulement les
-- colonnes lues ou ecrites. Une table deja creee par un jeu joue avant recoit les colonnes qui lui manquent (nullables, ou avec
-- un DEFAULT : d'autres jeux y inserent sans elles), et les lignes passent par sp_executesql (une colonne ajoutee dans ce lot
-- d'instructions n'existe pas encore quand SQL Server le compile). PAS d'IDENTITY : les jeux inserent leurs identifiants.
-- Ce qui est retenu ou ecarte, et pourquoi : PROC_RETAUD.attendu ; recherches : PROC_RETAUD.recherches ; gestes : PROC_RETAUD.gestes.
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_INSTANCE varchar(2) NULL;
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
